import 'dart:convert';import 'package:flutter_test/flutter_test.dart';import 'package:qros_mobile_studio/core/local_vault.dart';import 'package:qros_mobile_studio/core/remote_session.dart';String rep(String s,int n)=>List.filled(n,s).join();class G implements SessionGateway{int n=0;@override Future<RemoteSessionBundle> exchange(String o,String p,String c)async=>RemoteSessionBundle(origin:o,clientId:c,accessToken:rep('A',43),refreshToken:rep('R',43),accessExp:100,refreshExp:1000);@override Future<RemoteSessionBundle> refresh(RemoteSessionBundle c)async{n++;return RemoteSessionBundle(origin:c.origin,clientId:c.clientId,accessToken:rep('B',43),refreshToken:rep('S',43),accessExp:900,refreshExp:2000);}@override Future<void> revoke(RemoteSessionBundle c)async{}}void main(){test('pair persists and rotates',()async{final v=MemoryLocalVault(),g=G(),s=RemoteSessionStore(vault:v,gateway:g,clock:()=>DateTime.fromMillisecondsSinceEpoch(50000,isUtc:true));await s.pair('https://x.test',rep('P',43),'client_A');expect(await s.accessToken(),rep('B',43));expect(g.n,1);final r=RemoteSessionStore(vault:v,gateway:g,clock:()=>DateTime.fromMillisecondsSinceEpoch(200000,isUtc:true));await r.initialize();expect(r.paired,true);});test('expired refresh is removed',()async{final d={'schema':'QROS_REMOTE_SESSION_STORE_V1','origin':'https://x.test','client_id':'c','access_token':rep('A',43),'refresh_token':rep('R',43),'access_exp':1,'refresh_exp':2},v=MemoryLocalVault({RemoteSessionStore.storageKey:jsonEncode(d)}),s=RemoteSessionStore(vault:v,gateway:G(),clock:()=>DateTime.fromMillisecondsSinceEpoch(3000,isUtc:true));await s.initialize();expect(s.paired,false);});}